const html = $input.first().json.data;
const urlPattern = /href=["'](https:\/\/www\.datatalk\.cz\/akce\/[^"']+)["']/gi;
const matches = [...html.matchAll(urlPattern)];
const uniqueUrls = [...new Set(matches.map(m => m[1]))];

if (uniqueUrls.length === 0) {
  const altPattern = /href=["'](\/akce\/[^"']+)["']/gi;
  const altMatches = [...html.matchAll(altPattern)];
  const baseUrl = 'https://www.datatalk.cz';
  const altUrls = [...new Set(altMatches.map(m => baseUrl + m[1]))];
  return altUrls.map(url => ({ json: { eventUrl: url } }));
}

return uniqueUrls.map(url => ({ json: { eventUrl: url } }));

const html = $input.first().json.data;
const eventUrl = $('Loop Events').first().json.eventUrl;

let content = html;
content = content.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
content = content.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
content = content.replace(/<!--[\s\S]*?-->/g, '');
content = content.replace(/<h1[^>]*>(.*?)<\/h1>/gi, '\n# $1\n');
content = content.replace(/<h2[^>]*>(.*?)<\/h2>/gi, '\n## $1\n');
content = content.replace(/<h3[^>]*>(.*?)<\/h3>/gi, '\n### $1\n');
content = content.replace(/<p[^>]*>(.*?)<\/p>/gi, '\n$1\n');
content = content.replace(/<br\s*\/?>/gi, '\n');
content = content.replace(/<li[^>]*>(.*?)<\/li>/gi, '- $1\n');
content = content.replace(/<strong[^>]*>(.*?)<\/strong>/gi, '**$1**');
content = content.replace(/<[^>]+>/g, '');
content = content.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
content = content.replace(/\n\s*\n\s*\n/g, '\n\n').trim();
if (content.length > 8000) content = content.substring(0, 8000) + '...';

return [{ json: { eventUrl, markdown: content } }];

